// === Tab: mySketch ===
let colors = ["#f2eb8a", "#fed000", "#fc8405", "#ed361a", "#e2f0f3", "#b3dce0", "#4464a1", "#203051", "#ffc5c7", "#f398c3", "#cf3895", "#6d358a", "#06b4b0", "#4b8a5f"];

let mySeed;

let patterns = [];

function setup() {
	createCanvas(1000, 1000);
	ellipseMode(CENTER);
	rectMode(CENTER);
	mySeed = floor(random(1, 10000));
	let mySize = 100;

	patterns.push(new Pattern(width / 2, height / 2, width - mySize));

	for (let xx = mySize; xx <= width - mySize; xx += mySize) {
		for (let yy = mySize; yy <= height - mySize; yy += mySize) {
			if (random(0, 1) > 0.5) 
			{
				patterns.push(new Pattern(xx, yy, mySize));
			}
		}
	}

	 mySize /= 2;

	for(let xx = mySize;xx <=width-mySize;xx+=mySize)
	{
		for(let yy = mySize;yy <= height-mySize;yy+=mySize)
		{
			if (random(0,1) > 0.75)
			{
	    patterns.push(new Pattern(xx,yy,mySize));
			}
		}
	}

	noLoop();
}

function draw() {

	randomSeed(mySeed);
	fill(generateColor());
	square(width / 2, height / 2, width);

	for (let i = 0; i < patterns.length; i++) {
		patterns[i].draw();
	}

}

class Pattern {
	constructor(x, y, mySize) {
		this.x = x;
		this.y = y;
		this.size = mySize;
		this.color1 = generateColor();
		this.color2 = generateColor();
		this.angle = random([0, PI / 2,PI,3*PI/2]);
	}

	draw() {
		push();
		//strokeWeight(0.25);
		translate(this.x, this.y);
		rotate(this.angle);
		noFill();
		square(0, 0, this.size);
		fill(this.color1);
		arc(-this.size / 2, 0, this.size / 2, this.size / 2, 3 * PI / 2, PI / 2);
		arc(this.size / 2, 0, this.size / 2, this.size / 2, PI / 2, 3 * PI / 2);
		circle(0, 0, this.size / 3);

		fill(this.color2);
		arc(-this.size / 2, 0, this.size / 4, this.size / 4, 3 * PI / 2, PI / 2);
		arc(this.size / 2, 0, this.size / 4, this.size / 4, PI / 2, 3 * PI / 2);
		arc(0, -this.size / 2, this.size / 4, this.size / 4, 2 * PI, PI);
		arc(0, this.size / 2, this.size / 4, this.size / 4, PI, 2 * PI);

		pop();
	}
}

function generateColor() {
	return random(colors);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
